INSERT INTO reviews(name,location,rating,comment,status,created_at) SELECT 'Morgan Blake','Tennessee, USA',5,'Rated 5 stars, highlighting excellent communication throughout the shipping process for his emu eggs.','approved',datetime('now') WHERE NOT EXISTS(SELECT 1 FROM reviews WHERE name='Morgan Blake');
INSERT INTO reviews(name,location,rating,comment,status,created_at) SELECT 'Lyord Johnson','California, USA',4,'Rated 4 stars. One egg arrived broken during USPS delivery; the customer attributed the damage to USPS.','approved',datetime('now') WHERE NOT EXISTS(SELECT 1 FROM reviews WHERE name='Lyord Johnson');
INSERT INTO reviews(name,location,rating,comment,status,created_at) SELECT 'Catherine Hollender','New Jersey, USA',5,'Rated 5 stars. Her rhea chicks were well shipped and arrived healthy. She also expressed interest in buying again.','approved',datetime('now') WHERE NOT EXISTS(SELECT 1 FROM reviews WHERE name='Catherine Hollender');
INSERT INTO reviews(name,location,rating,comment,status,created_at) SELECT 'Deana Lindy','Utah, USA',4,'Rated 4 stars. It was her first time having peacocks, and they arrived safely and healthy.','approved',datetime('now') WHERE NOT EXISTS(SELECT 1 FROM reviews WHERE name='Deana Lindy');
INSERT INTO reviews(name,location,rating,comment,status,created_at) SELECT 'Houston Elvington','New Mexico, USA',5,'Rated 5 stars for the trio of four-year-old ostriches he received.','approved',datetime('now') WHERE NOT EXISTS(SELECT 1 FROM reviews WHERE name='Houston Elvington');
